SELECT 


    p.store_id = #{q.storeId}
    AND p.promo_type = #{q.promoType}
    AND p.status = #{q.status}

        AND p.status = 'ACTIVE'

            AND p.start_time > #{q.now}
            AND p.start_time <= #{q.now} AND p.end_time >= #{q.now}
            AND p.end_time < #{q.now}


    AND p.end_time >= #{q.beginDate}
    AND p.start_time < #{q.endNext}

        AND (p.name LIKE CONCAT('%', #{q.keyword}, '%')
             OR EXISTS (SELECT 1 FROM ecom_promotion_item i WHERE i.promotion_id = p.id AND i.seller_sku LIKE CONCAT('%', #{q.keyword}, '%')))


ORDER BY p.start_time DESC, p.id DESC

